36	// Kept as an exact fraction rather than `amount * 1.1`, which drifts in
37	// floating point (100 * 1.1 === 110.00000000000001).
38	const withFirstInsuranceSurcharge = (amount: number): number =>
39	  (amount * 11) / 10;
40	
41	const BLOCK_SIZE = 3;
42	const BLOCK_BASE_PREMIUM = 60;
43	
44	const isBlockOfAlikeComponents = (items: Item[]): boolean =>
45	  items.length === BLOCK_SIZE && items.every((item) => item.type === "rune");
46	
47	const policyBasePremiumOf = (items: Item[]): number => {
48	  if (isBlockOfAlikeComponents(items)) return BLOCK_BASE_PREMIUM;
49	  return items.reduce((sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type], 0);
50	};
51	
52	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
53	  const results = scenario.steps.map((step) => {
54	    const policyBasePremium = policyBasePremiumOf(step.items);
55	    const premium =
56	      withFirstInsuranceSurcharge(policyBasePremium) + PROCESSING_FEE;
57	    return { premium };
58	  });
59	
60	  return { results };
61	};
